// Package database owns the PostgreSQL connection pool.
//
// Query code is generated by sqlc into this package's sibling "store" package
// once the first product tables exist (see docs/implementation-plan.md).
package database

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
)

// NewPool parses the connection string and creates a pool.
// pgxpool connects lazily, so this succeeds even if PostgreSQL is not up yet;
// the health endpoint reports actual reachability.
func NewPool(ctx context.Context, databaseURL string) (*pgxpool.Pool, error) {
	poolConfig, err := pgxpool.ParseConfig(databaseURL)
	if err != nil {
		return nil, fmt.Errorf("parse database url: %w", err)
	}
	pool, err := pgxpool.NewWithConfig(ctx, poolConfig)
	if err != nil {
		return nil, fmt.Errorf("create pool: %w", err)
	}
	return pool, nil
}
